python3 - <<'PY'
import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
total=0
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H%x1f%B%x1e',f'origin/friend/{b}'],text=True)
    n=0
    for rec in out.split('\x1e'):
        if 'Friend-Message: 1' in rec:
            # episode line
            for line in rec.splitlines():
                if line.startswith('Episode:'):
                    ep=line.split(':',1)[1].strip()
                    if ep=='S06/E13':
                        n+=1
    total+=n
    print(b,n)
print('total',total)
